<script setup>
import { ref, onMounted, onUnmounted } from 'vue'
import MainLayout from '@/Layouts/MainLayout.vue'
import { useTranslations } from '@/composables/useTranslations'

import HeaderHero from "@/Components/headers/HeaderHero.vue"
import HeaderHeroBgImage from "@/Components/headers/HeaderHero_bg_image.vue"
import BaseTitle from "@/Components/Base/BaseTitle.vue"
import AgendaHome from "@/Components/widgets/AgendaHome.vue"
import HarmonyJourney from "@/Components/widgets/HarmonyJourney.vue"
import TitleImageGallery from "@/Components/widgets/TitleImageGallery.vue"

defineOptions({
    layout: MainLayout
})

// ============================================
// Composables
// ============================================

const { t } = useTranslations()
const windowWidth = ref(typeof window !== 'undefined' ? window.innerWidth : 1024)

// ============================================
// Blob Morph Animatie
// ============================================

const blobPath = ref(null)
let morphInterval = null
let morphTimeout = null
let isBlob1 = true

const blob1 = "M1030.79 22.3972C730.433 51.6333 344.76 22.3972 0 0V648.337C378.771 626.887 392.745 610.182 607.331 602.626C854.729 593.914 1095.15 615.328 1273.77 561.109C1478.83 498.862 1453.44 -18.7432 1030.79 22.3972Z"
const blob2 = "M1030.79 22.3972C725 -12.5 344.76 22.3972 0 0V648.337C378.771 626.887 323.913 597.057 538.5 589.5C785.898 580.788 1141 673.5 1273.77 561.109C1437.33 422.648 1452.7 70.5468 1030.79 22.3972Z"

const currentBlob = ref(blob1)

const morphBlob = () => {
    currentBlob.value = isBlob1 ? blob2 : blob1
    isBlob1 = !isBlob1
}

const blobPathM1 = ref(null)
let morphIntervalM1 = null
let morphTimeoutM1 = null
let isBlobM1 = true

// Eerste blob (originele)
const blobM1_1 = "M798.5 128C765.5 97.5 721.983 50.0365 633 58C504.5 69.5 372.5 33.3 292.5 18.5C212.5 3.7 64.1667 0 0 0V411.5C93.5 387 219.5 387.9 349.5 421.5C512 463.5 746 442.5 798.5 409V128Z"

// Tweede blob (nieuwe vorm)
const blobM1_2 = "M798.5 128C765.5 97.5 703.658 97.0058 615 86C470 68 373.857 18.5 292.5 18.5C186 18.5 64.1667 0 0 0V411.5C93.5 387 261.5 385.5 407.5 409C573.207 435.672 746 442.5 798.5 409V128Z"

const currentBlobM1 = ref(blobM1_1)

const morphBlobM1 = () => {
    currentBlobM1.value = isBlobM1 ? blobM1_2 : blobM1_1
    isBlobM1 = !isBlobM1
}


// ============================================
// Blob Morph Animatie - WieZijnWij
// ============================================

const blobPath2 = ref(null)
let morphInterval2 = null
let morphTimeout2 = null
let isBlob2_1 = true

// Eerste blob (originele)
const blob2_1 = "M775.481 0C1008.48 0.000201226 1261.98 52 1394.48 112V614C1394.48 614 1385.25 641.5 1281.48 768C1107.98 979.5 382.815 864.79 242.981 834.5C-64.0194 768 -3.51932 530 23.4806 417C84.136 163.146 516.32 -0.000223818 775.481 0Z"

// Tweede blob (nieuwe vorm)
const blob2_2 = "M755.027 0C988.026 0.000201227 1241.53 52 1374.03 112V614C1374.03 614 1328.55 725.351 1261.03 768C1071.05 888 400.38 881.29 260.546 851C3.02649 795.218 -8.95403 535 3.02655 417C38.9602 63.0798 495.866 -0.000223817 755.027 0Z"

const currentBlob2 = ref(blob2_1)

const morphBlob2 = () => {
    currentBlob2.value = isBlob2_1 ? blob2_2 : blob2_1
    isBlob2_1 = !isBlob2_1
}

const blobPathM2 = ref(null)
let morphIntervalM2 = null
let morphTimeoutM2 = null
let isBlobM2 = true

// Eerste blob (originele)
const blobM2_1 = "M236.361 35.7795C344.361 -29.0205 657.028 8.7793 799.361 35.7793L799.361 707.279C746.028 692.779 606.061 674.579 476.861 717.779C315.361 771.779 22.361 727.779 0.360973 698.779L0.360913 337.137C-0.15918 337.451 -0.0797945 337.059 0.360912 336.279L0.360913 337.137C2.39777 335.906 13.6293 323.84 48.3609 281.779C102.861 215.779 101.361 116.78 236.361 35.7795Z"

// Tweede blob (nieuwe vorm)
const blobM2_2 = "M236.082 24.089C356.516 -12.7718 656.749 -2.91123 799.082 24.0888L799.082 695.589C745.749 681.089 583.722 748.303 383.722 724.803C214.596 704.931 81.7217 669.303 0.0823706 687.089L0.0823104 324.848C-0.0259589 324.871 -0.0289048 324.786 0.0823104 324.589L0.0823104 324.848C2.08332 324.411 40.0602 286.679 58.2215 224.309C84.7216 133.303 86.7216 69.8033 236.082 24.089Z"

const currentBlobM2 = ref(blobM2_1)

const morphBlobM2 = () => {
    currentBlobM2.value = isBlobM2 ? blobM2_2 : blobM2_1
    isBlobM2 = !isBlobM2
}


// ============================================
// Window resize handler
// ============================================

const handleResize = () => {
    windowWidth.value = window.innerWidth
}

// ============================================
// Lifecycle Hooks
// ============================================

onMounted(() => {
    window.addEventListener('resize', handleResize)

    // Start blob morph 1 (OverOnsBlob) na 1 seconde
    morphTimeout = setTimeout(() => {
        morphBlob()
        morphInterval = setInterval(morphBlob, 6000)
    }, 1000)
    morphTimeout = setTimeout(() => {
        morphBlobM1()
        morphIntervalM1 = setInterval(morphBlobM1, 6000)
    }, 1000)

    // Start blob morph 2 (WieZijnWijBlob) na 2 seconde (iets later voor staggered effect)
    morphTimeout2 = setTimeout(() => {
        morphBlob2()
        morphInterval2 = setInterval(morphBlob2, 6000)
    }, 2000)
    morphTimeout = setTimeout(() => {
        morphBlobM2()
        morphIntervalM2 = setInterval(morphBlobM2, 6000)
    }, 1000)
})

onUnmounted(() => {
    window.removeEventListener('resize', handleResize)

    // Cleanup blob morph 1
    if (morphTimeout) clearTimeout(morphTimeout)
    if (morphInterval) clearInterval(morphInterval)
    if (morphTimeoutM1) clearTimeout(morphTimeoutM1)
    if (morphIntervalM1) clearInterval(morphIntervalM1)

    // Cleanup blob morph 2
    if (morphTimeout2) clearTimeout(morphTimeout2)
    if (morphInterval2) clearInterval(morphInterval2)
})
</script>

